============================================================ 
 Format Staff Follow-Up Task | n8n-nodes-base.code

const call = $('End Of Call-Webhook1').item.json.body.call;
const cad = (call.call_analysis || {}).custom_analysis_data || {};
const lead = $('Fetch Lead Details').item.json || {};
const centre = $('Lookup Centre SF').item.json || {};

const reason = cad.staff_followup_reason || 'other';
const reasonDisplay = reason.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const summary = cad.staff_followup_summary || cad.detailed_call_summary || 'No summary';
const parentName = (lead.First || cad['First Name'] || '') + ' ' + (lead.Last || '');
const parentNameClean = parentName.trim() || 'Unknown Parent';
const phone = lead.Phone || cad.Phone || call.to_number || '';
const email = lead.Email || '';
const callId = call.call_id || '';
const durationMin = Math.round((call.duration_ms || 0) / 60000);
const apptBooked = String(cad.appointment_booked) === 'true';

// Per-centre ClickUp routing from Lookup Centre SF
const listId = String(centre.clickup_outbound_list_id || '').trim();
const assigneeStr = String(centre.clickup_user_ids || '').trim();
const assignees = assigneeStr ? assigneeStr.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n)) : [];

const taskName = ('[Outbound Staff Follow-Up] ' + parentNameClean + ' - ' + summary).substring(0, 200);

let desc = '## Staff Follow-Up Required\n';
desc += '- **Reason:** ' + reasonDisplay + '\n';
desc += '- **Parent:** ' + parentNameClean + '\n';
desc += '- **Phone:** ' + phone + '\n';
desc += '- **Email:** ' + email + '\n';
desc += '- **Centre:** ' + (lead.centre_id || 'unknown') + ' (' + (centre.location_name || '?') + ')\n';
desc += '- **Director:** ' + (centre.Director || 'unknown') + '\n';
desc += '- **Duration:** ' + durationMin + ' min\n\n';

desc += '## What the AI Promised\n';
desc += summary + '\n\n';

if (apptBooked) {
  desc += '## Tour Also Booked on This Call\n';
  desc += '- **Date:** ' + (cad['Tour Date'] || 'Not specified') + '\n';
  desc += '- **Time:** ' + (cad['Tour Time'] || 'Not specified') + '\n';
  if (cad['Child First Name']) desc += '- **Child:** ' + cad['Child First Name'];
  if (cad["Child's Age"]) desc += ' (age ' + cad["Child's Age"] + ')';
  desc += '\n\n';
}

desc += '## Full Call Summary\n' + (cad.detailed_call_summary || call.call_analysis?.call_summary || 'No summary') + '\n\n';
desc += '## Recording\nhttps://app.retellai.com/calls/' + callId + '\n\n';
desc += '---\n_call_id: ' + callId + '_\n';

return [{
  json: {
    taskName,
    description: desc,
    priority: 3,
    tags: ['staff_followup', reason],
    listId,
    assignees,
    hasClickUpConfig: !!listId
  }
}];

