import os,urllib.request,json
key=os.environ.get('N8N_API_KEY',''); base="https://xprime17.app.n8n.cloud"
TOK="pk_114277538_QASW3X3E93S0MUL39MSA89ZI90NNSYDV"
DUE="due_date: Date.now() + 172800000, due_date_time: false"

def n8n(method,path,payload=None):
    data=json.dumps(payload).encode() if payload is not None else None
    r=urllib.request.Request(f"{base}/api/v1{path}",data=data,method=method,
        headers={'X-N8N-API-KEY':key,'Content-Type':'application/json'})
    return json.load(urllib.request.urlopen(r,timeout=60))

def patch_node(wf,node_name,replacements):
    for n in wf['nodes']:
        if n['name']==node_name:
            jb=n['parameters']['jsonBody']
            for old,new in replacements:
                assert old in jb, f"PATTERN NOT FOUND in {node_name}: {old[:40]}"
                jb=jb.replace(old,new,1)
            n['parameters']['jsonBody']=jb
            return True
    raise SystemExit(f"node {node_name} not found")

def deploy(wid,patches):
    wf=n8n('GET',f"/workflows/{wid}")
    for nm,reps in patches: patch_node(wf,nm,reps)
    payload={"name":wf["name"],"nodes":wf["nodes"],"connections":wf["connections"],"settings":wf.get("settings",{})}
    n8n('PUT',f"/workflows/{wid}",payload)
    # verify
    chk=n8n('GET',f"/workflows/{wid}")
    for nm,_ in patches:
        jb=[n for n in chk['nodes'] if n['name']==nm][0]['parameters']['jsonBody']
        print(f"   ✓ {wid}/{nm}: due_date present = {'due_date' in jb}")

print("=== OUTBOUND EOC ===")
deploy("4p1V0wESn3kZySt6",[
  ("Create Staff Follow-Up Task",[("assignees: $json.assignees}", f"assignees: $json.assignees, {DUE}}}")]),
])
print("=== INBOUND EOC ===")
deploy("3oV7SpPKWmr3xJlQ",[
  ("Create ClickUp Task",[("tags: $json.tags, assignees:", f"tags: $json.tags, {DUE}, assignees:")]),
  ("Create Cancel Task",[("assignees: [81534293, 87407960]", f"{DUE},\n      assignees: [81534293, 87407960]")]),
])

